(function (window, document) {
    'use strict';

    if (window.QmxUmlSoftwareDesignEditor?.version) return;
    const Diagram = window.QmxDiagram;
    if (!Diagram) { console.error('[QMX UML] Diagram renderer must load first.'); return; }

    const TOOL_DEFS = [
        ['select', 'Select', 'নির্বাচন'],
        ['class', 'Class', 'ক্লাস'],
        ['interface', 'Interface', 'ইন্টারফেস'],
        ['abstract', 'Abstract class', 'অ্যাবস্ট্রাক্ট ক্লাস'],
        ['enum', 'Enumeration', 'এনাম'],
        ['component', 'Component', 'কম্পোনেন্ট'],
        ['actor', 'Actor', 'অ্যাক্টর'],
        ['usecase', 'Use case', 'ইউজ কেস'],
        ['package', 'Package', 'প্যাকেজ'],
        ['note', 'Note', 'নোট'],
        ['uml-relation', 'Smart relation', 'স্মার্ট সম্পর্ক'],
        ['text', 'Annotation', 'টীকা']
    ];
    const PORTS = ['n', 'e', 's', 'w'];
    const NODE_TYPES = new Set(['uml-class', 'uml-component', 'uml-actor', 'uml-usecase', 'uml-package', 'uml-note']);

    const state = { root:null, canvas:null, svg:null, context:null, document:null, selectedId:null, activeTool:'select', interaction:null, connectionStart:null, history:[], historyIndex:-1, controls:{} };
    function uid(prefix='uml') { return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`; }
    function esc(value) { return String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]); }
    function clone(value) { return JSON.parse(JSON.stringify(value)); }
    function snap(value) { const step=Number(state.document?.gridSize||20); return state.document?.snap ? Math.round(value/step)*step : value; }
    function selectedObject() { return state.document?.objects.find((object)=>object.id===state.selectedId)||null; }
    function nodes() { return state.document?.objects.filter((object)=>NODE_TYPES.has(object.type))||[]; }

    function createDocument() {
        return { version:26, id:uid('uml-software-design'), mode:'uml-software-design', title:'UML / Software Architecture Diagram', width:1180, height:720, background:'#ffffff', gridSize:20, umlShowGrid:true, umlShowCompartments:true, umlShowMultiplicity:true, umlShowStereotypes:true, snap:true, objects:[] };
    }
    function makeClass(kind='class', overrides={}) {
        const names={class:'ClassName',interface:'Service',abstract:'AbstractBase',enum:'Status'};
        const stereotype=kind==='interface'?'interface':kind==='enum'?'enumeration':'';
        return { id:uid('uml-class'), type:'uml-class', classKind:kind, x:340, y:250, width:250, height:190, name:names[kind]||'ClassName', stereotype, attributes:kind==='enum'?['PENDING','ACTIVE','CLOSED']:['- id: int','+ name: string'], methods:kind==='enum'?[]:['+ getId(): int','+ save(): void'], fill:kind==='interface'?'#ecfeff':kind==='enum'?'#fef3c7':'#eff6ff', stroke:kind==='interface'?'#0e7490':kind==='enum'?'#b45309':'#1d4ed8', textColor:'#0f172a', lineWidth:2.5, ...overrides };
    }
    function makeComponent(overrides={}) { return { id:uid('uml-component'), type:'uml-component', x:360, y:260, width:230, height:120, name:'Component', stereotype:'component', description:'Responsibility', fill:'#f3e8ff', stroke:'#7e22ce', textColor:'#0f172a', lineWidth:2.5, ...overrides }; }
    function makeActor(overrides={}) { return { id:uid('uml-actor'), type:'uml-actor', x:220, y:280, width:100, height:150, label:'Actor', stroke:'#334155', textColor:'#0f172a', lineWidth:3, ...overrides }; }
    function makeUsecase(overrides={}) { return { id:uid('uml-usecase'), type:'uml-usecase', x:500, y:280, width:240, height:110, label:'Use case', fill:'#f8fafc', stroke:'#475569', textColor:'#0f172a', lineWidth:2.5, ...overrides }; }
    function makePackage(overrides={}) { return { id:uid('uml-package'), type:'uml-package', x:560, y:370, width:620, height:430, label:'Package', fill:'#f8fafc', stroke:'#64748b', textColor:'#0f172a', lineWidth:2, dashed:false, ...overrides }; }
    function makeNote(overrides={}) { return { id:uid('uml-note'), type:'uml-note', x:780, y:180, width:260, height:130, text:'Design note', fill:'#fef9c3', stroke:'#ca8a04', textColor:'#713f12', lineWidth:2, ...overrides }; }
    function defaultObject(type) {
        if (['class','interface','abstract','enum'].includes(type)) return makeClass(type);
        if (type==='component') return makeComponent();
        if (type==='actor') return makeActor();
        if (type==='usecase') return makeUsecase();
        if (type==='package') return makePackage();
        if (type==='note') return makeNote();
        return { id:uid('text'), type:'text', x:80, y:80, text:'UML diagram', color:'#0f172a', fontSize:20, fontWeight:'bold' };
    }
    function bounds(object) {
        const w=Number(object.width||200), h=Number(object.height||120); return { left:Number(object.x||0)-w/2, top:Number(object.y||0)-h/2, width:w, height:h };
    }
    function portPosition(object,key) { const b=bounds(object); if(key==='n')return{x:object.x,y:b.top,key}; if(key==='s')return{x:object.x,y:b.top+b.height,key}; if(key==='w')return{x:b.left,y:object.y,key}; return{x:b.left+b.width,y:object.y,key:'e'}; }
    function addRelation(sourceObject,sourceKey,targetObject,targetKey,overrides={}) {
        const relation={ id:uid('uml-relation'), type:'uml-relation', sourceId:sourceObject.id, targetId:targetObject.id, sourcePort:sourceKey||'e', targetPort:targetKey||'w', relationType:'association', label:'', sourceMultiplicity:'', targetMultiplicity:'', stroke:'#334155', lineWidth:2.5, autoRoute:true, ...overrides };
        state.document.objects.push(relation); state.selectedId=relation.id; state.connectionStart=null; pushHistory(); render(); setStatus('Smart point-to-point UML relationship created.');
    }
    function connectPort(objectId,portKey) {
        const object=state.document.objects.find((item)=>item.id===objectId&&NODE_TYPES.has(item.type)); if(!object)return;
        if(!state.connectionStart){state.connectionStart={objectId,portKey};setStatus('Source selected. Choose a destination connection point.');render();return;}
        const source=state.document.objects.find((item)=>item.id===state.connectionStart.objectId&&NODE_TYPES.has(item.type)); if(!source){state.connectionStart=null;render();return;}
        addRelation(source,state.connectionStart.portKey,object,portKey); state.activeTool='select'; updateToolButtons();
    }
    function addObject(type){const object=defaultObject(type);const count=state.document.objects.length;if('x'in object)object.x=snap(Number(object.x)+(count%5)*24);if('y'in object)object.y=snap(Number(object.y)+(count%4)*24);state.document.objects.push(object);state.selectedId=object.id;pushHistory();render();setStatus(`${type} added.`);}
    function pushHistory(){if(!state.document)return;const snapshot=JSON.stringify(state.document);if(state.history[state.historyIndex]===snapshot)return;state.history=state.history.slice(0,state.historyIndex+1);state.history.push(snapshot);if(state.history.length>100)state.history.shift();state.historyIndex=state.history.length-1;updateHistoryButtons();}
    function restoreHistory(index){if(index<0||index>=state.history.length)return;state.historyIndex=index;state.document=Diagram.normalizeSpec(JSON.parse(state.history[index]));state.selectedId=null;state.connectionStart=null;state.interaction=null;syncDocumentControls();render();updateHistoryButtons();}
    function undo(){restoreHistory(state.historyIndex-1);} function redo(){restoreHistory(state.historyIndex+1);}
    function updateHistoryButtons(){if(!state.controls.undo)return;state.controls.undo.disabled=state.historyIndex<=0;state.controls.redo.disabled=state.historyIndex>=state.history.length-1;}
    function updateToolButtons(){state.controls.tools?.querySelectorAll('[data-tool]').forEach((button)=>button.classList.toggle('active',button.dataset.tool===state.activeTool));}
    function setTool(tool){state.activeTool=tool;state.connectionStart=null;updateToolButtons();if(tool==='uml-relation'){setStatus('Smart relation: click a source point, then a destination point.');render();return;}if(tool!=='select'){addObject(tool);state.activeTool='select';updateToolButtons();}else render();}
    function selectionMarkup(){if(!state.document)return'';const selected=selectedObject();let markup='<g data-uml-editor-overlay="1">';if(selected&&NODE_TYPES.has(selected.type)){const b=bounds(selected);markup+=`<rect x="${b.left-8}" y="${b.top-8}" width="${b.width+16}" height="${b.height+16}" rx="8" fill="none" stroke="#2563eb" stroke-width="2" stroke-dasharray="7 5"/>`;}else if(selected?.type==='text')markup+=`<circle cx="${selected.x}" cy="${selected.y}" r="8" fill="#2563eb" stroke="#fff" stroke-width="2"/>`;if(state.activeTool==='uml-relation'||(selected&&NODE_TYPES.has(selected.type))){nodes().forEach((object)=>PORTS.forEach((key)=>{const point=portPosition(object,key);const started=state.connectionStart?.objectId===object.id&&state.connectionStart?.portKey===key;markup+=`<circle data-uml-port-object="${esc(object.id)}" data-uml-port-key="${key}" cx="${point.x}" cy="${point.y}" r="${started?9:7}" fill="${started?'#16a34a':'#2563eb'}" stroke="#fff" stroke-width="2" style="cursor:crosshair"/>`;}));}return markup+'</g>';}
    function render(){if(!state.canvas||!state.document)return;state.document=Diagram.normalizeSpec(state.document);let svg=Diagram.svgMarkup(state.document);svg=svg.replace('</svg>',`${selectionMarkup()}</svg>`);state.canvas.innerHTML=svg;state.svg=state.canvas.querySelector('svg');syncSelectedControls();updateSummary();}

    function field(label,key,value,type='text',attrs=''){return`<div class="qmx-uml-field"><label>${esc(label)}</label><input type="${type}" data-object="${esc(key)}" value="${esc(value)}" ${attrs}></div>`;}
    function check(label,key,checked){return`<label class="qmx-uml-check"><input type="checkbox" data-object="${esc(key)}" ${checked?'checked':''}> ${esc(label)}</label>`;}
    function textarea(label,key,value){return`<div class="qmx-uml-field"><label>${esc(label)}</label><textarea data-object="${esc(key)}">${esc(value)}</textarea></div>`;}
    function selectField(label,key,value,values){return`<div class="qmx-uml-field"><label>${esc(label)}</label><select data-object="${esc(key)}">${values.map((item)=>`<option value="${esc(item)}" ${item===value?'selected':''}>${esc(item)}</option>`).join('')}</select></div>`;}
    function syncSelectedControls(){const panel=state.controls.selected;if(!panel)return;const object=selectedObject();if(!object){panel.innerHTML='<div class="qmx-uml-empty">Select a UML element or relationship.</div>';return;}let html=`<div class="qmx-uml-type">${esc(object.type)}${object.classKind?` · ${esc(object.classKind)}`:''}</div>`;
        if(object.type==='uml-class'){html+=selectField('Classifier kind','classKind',object.classKind,['class','interface','abstract','enum']);html+=field('Name','name',object.name);html+=field('Stereotype','stereotype',object.stereotype||'');html+=textarea('Attributes / literals — one per line','attributesText',(object.attributes||[]).join('\n'));html+=textarea('Operations — one per line','methodsText',(object.methods||[]).join('\n'));html+=`<div class="qmx-uml-grid2">${field('X','x',object.x,'number')}${field('Y','y',object.y,'number')}${field('Width','width',object.width,'number','min="140" max="900"')}${field('Height','height',object.height,'number','min="90" max="900"')}</div>`;html+=`<div class="qmx-uml-grid2">${field('Fill','fill',object.fill,'color')}${field('Stroke','stroke',object.stroke,'color')}${field('Text','textColor',object.textColor,'color')}${field('Line width','lineWidth',object.lineWidth,'number','min="1" max="12" step="0.5"')}</div>`;}
        else if(object.type==='uml-component'){html+=field('Name','name',object.name);html+=field('Stereotype','stereotype',object.stereotype||'component');html+=textarea('Description','description',object.description||'');html+=sizeFields(object);}
        else if(object.type==='uml-actor'){html+=field('Actor label','label',object.label);html+=positionFields(object);}
        else if(object.type==='uml-usecase'){html+=field('Use-case label','label',object.label);html+=sizeFields(object);}
        else if(object.type==='uml-package'){html+=field('Package label','label',object.label);html+=sizeFields(object);html+=check('Dashed border','dashed',object.dashed);}
        else if(object.type==='uml-note'){html+=textarea('Note text','text',object.text);html+=sizeFields(object);}
        else if(object.type==='uml-relation'){const options=(selectedId)=>nodes().map((item)=>`<option value="${esc(item.id)}" ${item.id===selectedId?'selected':''}>${esc(item.name||item.label||item.type)}</option>`).join('');const portOptions=(key)=>PORTS.map((p)=>`<option value="${p}" ${p===key?'selected':''}>${p.toUpperCase()}</option>`).join('');html+=selectField('Relationship type','relationType',object.relationType,['association','dependency','generalization','realization','aggregation','composition']);html+=field('Label','label',object.label||'');html+=`<div class="qmx-uml-grid2">${field('Source multiplicity','sourceMultiplicity',object.sourceMultiplicity||'')}${field('Target multiplicity','targetMultiplicity',object.targetMultiplicity||'')}</div>`;html+=`<div class="qmx-uml-field"><label>Source</label><select data-object="sourceId">${options(object.sourceId)}</select></div><div class="qmx-uml-field"><label>Target</label><select data-object="targetId">${options(object.targetId)}</select></div><div class="qmx-uml-grid2"><div class="qmx-uml-field"><label>Source port</label><select data-object="sourcePort">${portOptions(object.sourcePort)}</select></div><div class="qmx-uml-field"><label>Target port</label><select data-object="targetPort">${portOptions(object.targetPort)}</select></div></div>`;html+=check('Automatic orthogonal route','autoRoute',object.autoRoute);html+=`<div class="qmx-uml-grid2">${field('Stroke','stroke',object.stroke,'color')}${field('Line width','lineWidth',object.lineWidth,'number','min="1" max="12" step="0.5"')}</div>`;}
        else {html+=textarea('Text','text',object.text);html+=positionFields(object);html+=field('Font size','fontSize',object.fontSize,'number','min="8" max="120"');html+=field('Color','color',object.color,'color');html+=check('Bold','fontWeight',object.fontWeight==='bold');}
        panel.innerHTML=html;
    }
    function positionFields(object){return`<div class="qmx-uml-grid2">${field('X','x',object.x,'number')}${field('Y','y',object.y,'number')}</div>`;}
    function sizeFields(object){return`${positionFields(object)}<div class="qmx-uml-grid2">${field('Width','width',object.width,'number','min="70" max="1600"')}${field('Height','height',object.height,'number','min="60" max="1200"')}</div><div class="qmx-uml-grid2">${field('Fill','fill',object.fill||'#ffffff','color')}${field('Stroke','stroke',object.stroke||'#334155','color')}</div>`;}
    function updateSummary(){const counts={};state.document.objects.forEach((object)=>{counts[object.type]=(counts[object.type]||0)+1;});state.controls.summary.textContent=`${state.document.objects.length} object(s) · ${counts['uml-class']||0} classifier · ${counts['uml-relation']||0} relation · ${counts['uml-usecase']||0} use case`;}
    function syncDocumentControls(){state.root.querySelectorAll('[data-doc]').forEach((input)=>{const key=input.dataset.doc;if(input.type==='checkbox')input.checked=Boolean(state.document[key]);else input.value=state.document[key]??'';});}
    function onRootInput(event){const docKey=event.target.dataset.doc;if(docKey){let value=event.target.type==='checkbox'?event.target.checked:event.target.value;if(event.target.type==='number')value=Number(value);state.document[docKey]=value;render();return;}const key=event.target.dataset.object;if(!key)return;const object=selectedObject();if(!object)return;let value=event.target.type==='checkbox'?event.target.checked:event.target.value;if(event.target.type==='number')value=Number(value);if(key==='attributesText'){object.attributes=String(value).split(/\r?\n/).filter(Boolean);}else if(key==='methodsText'){object.methods=String(value).split(/\r?\n/).filter(Boolean);}else if(key==='fontWeight'){object.fontWeight=value?'bold':'normal';}else object[key]=value;render();}
    function svgPoint(event){if(!state.svg)return{x:0,y:0};const rect=state.svg.getBoundingClientRect();return{x:(event.clientX-rect.left)*state.document.width/rect.width,y:(event.clientY-rect.top)*state.document.height/rect.height};}
    function onCanvasPointerDown(event){const port=event.target.closest?.('[data-uml-port-object]');if(port){connectPort(port.dataset.umlPortObject,port.dataset.umlPortKey);event.preventDefault();return;}const target=event.target.closest?.('[data-qmx-object]');if(!target){state.selectedId=null;render();return;}const object=state.document.objects.find((item)=>item.id===target.dataset.qmxObject);if(!object)return;state.selectedId=object.id;if(state.activeTool==='uml-relation'&&NODE_TYPES.has(object.type)){const point=svgPoint(event);const nearest=PORTS.map((key)=>portPosition(object,key)).sort((a,b)=>Math.hypot(a.x-point.x,a.y-point.y)-Math.hypot(b.x-point.x,b.y-point.y))[0];connectPort(object.id,nearest.key);event.preventDefault();return;}if(object.type!=='uml-relation'){const point=svgPoint(event);state.interaction={id:object.id,startX:point.x,startY:point.y,origX:Number(object.x||0),origY:Number(object.y||0)};event.target.setPointerCapture?.(event.pointerId);}render();}
    function onPointerMove(event){if(!state.interaction)return;const object=state.document.objects.find((item)=>item.id===state.interaction.id);if(!object)return;const point=svgPoint(event);object.x=snap(state.interaction.origX+point.x-state.interaction.startX);object.y=snap(state.interaction.origY+point.y-state.interaction.startY);render();}
    function onPointerUp(){if(!state.interaction)return;state.interaction=null;pushHistory();setStatus('Object moved; attached UML relationships rerouted automatically.');}
    function onRootClick(event){const tool=event.target.closest?.('[data-tool]')?.dataset.tool;if(tool){setTool(tool);return;}const preset=event.target.closest?.('[data-preset]')?.dataset.preset;if(preset){applyPreset(preset);return;}const act=event.target.closest?.('[data-act]')?.dataset.act;if(!act)return;({new:newDocument,undo,redo,duplicate:duplicateSelected,delete:deleteSelected,close,insert:insertIntoQuestion,'export-svg':exportSvg,'export-png':exportPng}[act]||(()=>{}))();}
    function relation(source,target,options={}){return{id:uid('uml-relation'),type:'uml-relation',sourceId:source.id,targetId:target.id,sourcePort:options.sourcePort||'e',targetPort:options.targetPort||'w',relationType:options.relationType||'association',label:options.label||'',sourceMultiplicity:options.sourceMultiplicity||'',targetMultiplicity:options.targetMultiplicity||'',stroke:options.stroke||'#334155',lineWidth:options.lineWidth||2.5,autoRoute:true};}
    function noteText(x,y,text,options={}){return{id:uid('text'),type:'text',x,y,text,color:options.color||'#0f172a',fontSize:options.fontSize||20,fontWeight:options.bold===false?'normal':'bold'};}
    function applyPreset(type){let objects=[];let title='UML / Software Architecture Diagram';
        if(type==='student-course'){const student=makeClass('class',{x:260,y:260,name:'Student',attributes:['- studentId: int','- name: string'],methods:['+ enroll(course): void']});const course=makeClass('class',{x:790,y:260,name:'Course',attributes:['- code: string','- title: string'],methods:['+ addStudent(student): void']});objects=[student,course,relation(student,course,{label:'enrolls',sourceMultiplicity:'0..*',targetMultiplicity:'0..*'})];title='Student–Course Class Diagram';}
        else if(type==='ecommerce'){const customer=makeClass('class',{x:190,y:190,name:'Customer'});const order=makeClass('class',{x:520,y:190,name:'Order',attributes:['- orderNo: string','- total: decimal']});const item=makeClass('class',{x:850,y:190,name:'OrderItem',attributes:['- quantity: int','- price: decimal']});const product=makeClass('class',{x:850,y:500,name:'Product'});objects=[customer,order,item,product,relation(customer,order,{label:'places',sourceMultiplicity:'1',targetMultiplicity:'0..*'}),relation(order,item,{relationType:'composition',sourceMultiplicity:'1',targetMultiplicity:'1..*'}),relation(item,product,{sourceMultiplicity:'0..*',targetMultiplicity:'1'})];title='E-commerce Domain Model';}
        else if(type==='inheritance'){const shape=makeClass('abstract',{x:570,y:150,name:'Shape',attributes:['# color: string'],methods:['+ area(): number']});const circle=makeClass('class',{x:300,y:470,name:'Circle',attributes:['- radius: number']});const rectangle=makeClass('class',{x:820,y:470,name:'Rectangle',attributes:['- width: number','- height: number']});objects=[shape,circle,rectangle,relation(circle,shape,{relationType:'generalization',sourcePort:'n',targetPort:'s'}),relation(rectangle,shape,{relationType:'generalization',sourcePort:'n',targetPort:'s'})];title='Inheritance / Generalization';}
        else if(type==='observer'){const subject=makeClass('interface',{x:300,y:180,name:'Subject',methods:['+ attach(o): void','+ notify(): void']});const observer=makeClass('interface',{x:820,y:180,name:'Observer',methods:['+ update(): void']});const concreteSubject=makeClass('class',{x:300,y:500,name:'ConcreteSubject'});const concreteObserver=makeClass('class',{x:820,y:500,name:'ConcreteObserver'});objects=[subject,observer,concreteSubject,concreteObserver,relation(concreteSubject,subject,{relationType:'realization',sourcePort:'n',targetPort:'s'}),relation(concreteObserver,observer,{relationType:'realization',sourcePort:'n',targetPort:'s'}),relation(subject,observer,{label:'notifies',sourceMultiplicity:'1',targetMultiplicity:'0..*'})];title='Observer Design Pattern';}
        else if(type==='mvc'){const model=makeComponent({x:240,y:350,name:'Model',description:'Domain and persistence'});const view=makeComponent({x:590,y:160,name:'View',description:'User interface'});const controller=makeComponent({x:940,y:350,name:'Controller',description:'Input coordination'});objects=[model,view,controller,relation(controller,model,{relationType:'dependency',label:'updates'}),relation(controller,view,{relationType:'dependency',label:'selects'}),relation(view,model,{relationType:'dependency',label:'observes',sourcePort:'w',targetPort:'e'})];title='MVC Software Architecture';}
        else if(type==='usecase'){const actor=makeActor({x:190,y:330,label:'Customer'});const login=makeUsecase({x:520,y:190,label:'Sign in'});const checkout=makeUsecase({x:520,y:350,label:'Checkout'});const pay=makeUsecase({x:850,y:350,label:'Process payment'});const boundary=makePackage({x:660,y:330,width:760,height:500,label:'E-commerce System'});objects=[boundary,actor,login,checkout,pay,relation(actor,login),relation(actor,checkout),relation(checkout,pay,{relationType:'dependency',label:'«include»'})];title='Use-case Overview';}
        else if(type==='component-architecture'){const ui=makeComponent({x:180,y:220,name:'Web UI'});const api=makeComponent({x:500,y:220,name:'REST API'});const service=makeComponent({x:820,y:220,name:'Domain Service'});const db=makeComponent({x:820,y:500,name:'Repository'});objects=[ui,api,service,db,relation(ui,api,{relationType:'dependency',label:'HTTPS'}),relation(api,service,{relationType:'dependency'}),relation(service,db,{relationType:'dependency'})];title='Component Architecture';}
        else if(type==='enum-example'){const order=makeClass('class',{x:330,y:300,name:'Order',attributes:['- status: OrderStatus'],methods:['+ submit(): void']});const status=makeClass('enum',{x:820,y:300,name:'OrderStatus',attributes:['DRAFT','SUBMITTED','PAID','CANCELLED']});objects=[order,status,relation(order,status,{relationType:'dependency',label:'uses'})];title='Enumeration Example';}
        else if(type==='clear'){objects=[];title=state.document.title;}
        state.document.objects=objects;state.document.title=title;state.selectedId=null;state.connectionStart=null;pushHistory();syncDocumentControls();render();setStatus(`${type} preset loaded.`);
    }
    function deleteSelected(){if(!state.selectedId)return;const id=state.selectedId;state.document.objects=state.document.objects.filter((object)=>object.id!==id&&object.sourceId!==id&&object.targetId!==id);state.selectedId=null;pushHistory();render();setStatus('Selected object deleted.');}
    function duplicateSelected(){const object=selectedObject();if(!object||object.type==='uml-relation')return;const copy=clone(object);copy.id=uid(object.type);copy.x=Number(copy.x||0)+30;copy.y=Number(copy.y||0)+30;state.document.objects.push(copy);state.selectedId=copy.id;pushHistory();render();setStatus('Object duplicated.');}
    function newDocument(){state.document=createDocument();state.selectedId=null;state.connectionStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();render();setStatus('New UML document created.');}
    function makeToken(){return`[[qmx-diagram:${Diagram.encodeSpec(state.document)}]]`;}
    function insertIntoQuestion(){const textarea=state.context?.textarea||window.QmxDiagramLauncher?.getActiveTextarea?.();if(!textarea){setStatus('No active question textarea found.');return;}const token=makeToken();if(state.context?.replaceRange){const{start,end}=state.context.replaceRange;textarea.setRangeText(token,start,end,'end');state.context.replaceRange={start,end:start+token.length};}else{const start=textarea.selectionStart??textarea.value.length;const end=textarea.selectionEnd??start;textarea.setRangeText(token,start,end,'end');state.context.replaceRange={start,end:start+token.length};}textarea.dispatchEvent(new Event('input',{bubbles:true}));textarea.dispatchEvent(new Event('change',{bubbles:true}));setStatus('UML diagram inserted into the question.');close();}
    function safeFilename(value){return String(value||'uml-software-design').replace(/[\\/:*?"<>|]+/g,'-').trim()||'uml-software-design';}
    function downloadBlob(blob,filename){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1000);}
    function exportSvg(){downloadBlob(new Blob([Diagram.svgMarkup(state.document)],{type:'image/svg+xml;charset=utf-8'}),`${safeFilename(state.document.title)}.svg`);setStatus('SVG exported.');}
    function exportPng(){const svg=Diagram.svgMarkup(state.document);const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=state.document.width;canvas.height=state.document.height;canvas.getContext('2d').drawImage(image,0,0);URL.revokeObjectURL(url);canvas.toBlob((blob)=>blob&&downloadBlob(blob,`${safeFilename(state.document.title)}.png`),'image/png');setStatus('PNG exported.');};image.onerror=()=>{URL.revokeObjectURL(url);setStatus('PNG export failed.');};image.src=url;}
    function addStyles(){if(document.getElementById('qmx-uml-editor-styles'))return;const style=document.createElement('style');style.id='qmx-uml-editor-styles';style.textContent=`.qmx-uml-editor{position:fixed;inset:0;z-index:100000;background:rgba(15,23,42,.72);padding:18px;box-sizing:border-box}.qmx-uml-shell{width:min(1540px,calc(100vw - 36px));height:calc(100vh - 36px);margin:auto;background:#f8fafc;border-radius:14px;display:grid;grid-template-rows:auto minmax(0,1fr) auto;overflow:hidden;box-shadow:0 24px 70px rgba(15,23,42,.35)}.qmx-uml-header,.qmx-uml-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;background:#fff;border-bottom:1px solid #e2e8f0}.qmx-uml-footer{border-top:1px solid #e2e8f0;border-bottom:0}.qmx-uml-title{font-weight:900;font-size:18px}.qmx-uml-subtitle{font-size:12px;color:#64748b}.qmx-uml-actions{display:flex;flex-wrap:wrap;gap:7px}.qmx-uml-btn,.qmx-uml-tool,.qmx-uml-preset{border:1px solid #cbd5e1;background:#fff;border-radius:8px;padding:8px 10px;cursor:pointer;font:inherit}.qmx-uml-btn.primary{background:#2563eb;color:#fff;border-color:#2563eb}.qmx-uml-tool,.qmx-uml-preset{min-width:0;width:100%;white-space:normal;overflow-wrap:anywhere;line-height:1.25;text-align:center;user-select:none}.qmx-uml-header>div:first-child{min-width:0}.qmx-uml-actions{min-width:0}.qmx-uml-btn.danger{color:#b91c1c}.qmx-uml-main{display:grid;grid-template-columns:260px minmax(520px,1fr) 320px;gap:10px;padding:10px;min-height:0;min-width:0}.qmx-uml-panel{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:10px;overflow-y:auto;overflow-x:hidden;min-width:0}.qmx-uml-tools,.qmx-uml-presets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:9px;min-width:0}.qmx-uml-tool small{display:block;color:#64748b}.qmx-uml-tool.active{border-color:#2563eb;background:#eff6ff;color:#1d4ed8}.qmx-uml-section{font-weight:800;margin-top:14px;padding-top:10px;border-top:1px solid #e2e8f0}.qmx-uml-canvas-wrap{min-width:0;min-height:0;background:#cbd5e1;border-radius:12px;padding:10px;overflow:auto;display:flex;align-items:center;justify-content:center}.qmx-uml-canvas{width:100%;min-width:560px}.qmx-uml-canvas svg{display:block;width:100%;height:auto;max-height:770px;background:#fff;box-shadow:0 8px 30px rgba(15,23,42,.16);touch-action:none}.qmx-uml-canvas [data-qmx-object]{cursor:move}.qmx-uml-field{margin:7px 0;min-width:0}.qmx-uml-field label{display:block;font-weight:700;font-size:12px;margin-bottom:4px}.qmx-uml-field input,.qmx-uml-field select,.qmx-uml-field textarea{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:8px;padding:8px;font:inherit}.qmx-uml-field textarea{min-height:76px;resize:vertical}.qmx-uml-grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.qmx-uml-grid2>*{min-width:0}.qmx-uml-check{display:block;margin:8px 0}.qmx-uml-type,.qmx-uml-summary{margin-top:8px;padding:9px;border-radius:8px;background:#eff6ff;color:#1d4ed8;font-size:12px}.qmx-uml-empty{color:#64748b;text-align:center;padding:20px 4px}.qmx-uml-status{color:#64748b;min-height:18px}@media(max-width:1250px){.qmx-uml-main{grid-template-columns:230px minmax(460px,1fr) 290px}}@media(max-width:1050px){.qmx-uml-editor{padding:0}.qmx-uml-shell{width:100vw;height:100vh;border-radius:0}.qmx-uml-main{grid-template-columns:220px minmax(0,1fr)}.qmx-uml-main>.qmx-uml-panel:last-child{grid-column:1/-1;max-height:300px}.qmx-uml-title{font-size:15px}}@media(max-width:720px){.qmx-uml-header,.qmx-uml-footer{align-items:flex-start;flex-direction:column}.qmx-uml-actions{width:100%}.qmx-uml-main{grid-template-columns:minmax(0,1fr);overflow:auto}.qmx-uml-main>.qmx-uml-panel:first-child{max-height:300px}.qmx-uml-main>.qmx-uml-panel:last-child{grid-column:auto;max-height:360px}.qmx-uml-canvas-wrap{min-height:420px}.qmx-uml-canvas{min-width:520px}.qmx-uml-footer .qmx-uml-actions{justify-content:flex-end}}`;document.head.appendChild(style);}
    function buildEditor(){if(state.root)return;addStyles();const root=document.createElement('div');root.className='qmx-uml-editor';root.hidden=true;root.innerHTML=`<div class="qmx-uml-shell" role="dialog" aria-modal="true" aria-label="UML and software architecture editor"><header class="qmx-uml-header"><div><div class="qmx-uml-title">UML / Software Architecture Diagram</div><div class="qmx-uml-subtitle">Classifiers, use cases, components, packages and smart point-to-point relationships</div></div><div class="qmx-uml-actions"><button class="qmx-uml-btn" data-act="new">New</button><button class="qmx-uml-btn" data-act="undo">Undo</button><button class="qmx-uml-btn" data-act="redo">Redo</button><button class="qmx-uml-btn" data-act="duplicate">Duplicate</button><button class="qmx-uml-btn danger" data-act="delete">Delete</button><button class="qmx-uml-btn" data-act="close">×</button></div></header><main class="qmx-uml-main"><aside class="qmx-uml-panel"><strong>UML elements & tools</strong><div class="qmx-uml-tools" data-tools></div><div class="qmx-uml-section">Diagram presets</div><div class="qmx-uml-presets"><button class="qmx-uml-preset" data-preset="student-course">Student–Course</button><button class="qmx-uml-preset" data-preset="ecommerce">E-commerce</button><button class="qmx-uml-preset" data-preset="inheritance">Inheritance</button><button class="qmx-uml-preset" data-preset="observer">Observer</button><button class="qmx-uml-preset" data-preset="mvc">MVC</button><button class="qmx-uml-preset" data-preset="usecase">Use case</button><button class="qmx-uml-preset" data-preset="component-architecture">Components</button><button class="qmx-uml-preset" data-preset="enum-example">Enumeration</button><button class="qmx-uml-preset" data-preset="clear">Clear</button></div><p class="qmx-uml-subtitle">Choose Smart relation, click a source connection point, then a destination. Relationships stay attached while elements move.</p></aside><section class="qmx-uml-canvas-wrap"><div class="qmx-uml-canvas" data-canvas></div></section><aside class="qmx-uml-panel"><strong>Document</strong><div class="qmx-uml-field"><label>Title</label><input data-doc="title"></div><div class="qmx-uml-grid2"><div class="qmx-uml-field"><label>Width</label><input type="number" min="480" max="2400" data-doc="width"></div><div class="qmx-uml-field"><label>Height</label><input type="number" min="300" max="1800" data-doc="height"></div><div class="qmx-uml-field"><label>Grid size</label><input type="number" min="5" max="100" data-doc="gridSize"></div><div class="qmx-uml-field"><label>Background</label><input type="color" data-doc="background"></div></div><label class="qmx-uml-check"><input type="checkbox" data-doc="umlShowGrid"> Show grid</label><label class="qmx-uml-check"><input type="checkbox" data-doc="umlShowCompartments"> Show class compartments</label><label class="qmx-uml-check"><input type="checkbox" data-doc="umlShowMultiplicity"> Show multiplicity</label><label class="qmx-uml-check"><input type="checkbox" data-doc="umlShowStereotypes"> Show stereotypes</label><label class="qmx-uml-check"><input type="checkbox" data-doc="snap"> Snap to grid</label><hr><strong>Selected object</strong><div data-selected></div><div class="qmx-uml-summary" data-summary></div></aside></main><footer class="qmx-uml-footer"><div class="qmx-uml-status" data-status></div><div class="qmx-uml-actions"><button class="qmx-uml-btn" data-act="export-svg">Export SVG</button><button class="qmx-uml-btn" data-act="export-png">Export PNG</button><button class="qmx-uml-btn primary" data-act="insert">Insert into question</button></div></footer></div>`;document.body.appendChild(root);state.root=root;state.canvas=root.querySelector('[data-canvas]');state.controls={tools:root.querySelector('[data-tools]'),selected:root.querySelector('[data-selected]'),summary:root.querySelector('[data-summary]'),status:root.querySelector('[data-status]'),undo:root.querySelector('[data-act="undo"]'),redo:root.querySelector('[data-act="redo"]')};TOOL_DEFS.forEach(([id,label,bn])=>{const button=document.createElement('button');button.className='qmx-uml-tool';button.dataset.tool=id;button.innerHTML=window.QmxDiagramToolButtonContent?window.QmxDiagramToolButtonContent(id,label,bn):`${esc(label)}<small>${esc(bn)}</small>`;state.controls.tools.appendChild(button);});root.addEventListener('click',onRootClick);root.addEventListener('change',onRootInput);root.addEventListener('input',onRootInput);state.canvas.addEventListener('pointerdown',onCanvasPointerDown);document.addEventListener('pointermove',onPointerMove);document.addEventListener('pointerup',onPointerUp);document.addEventListener('keydown',onKeydown);}
    function setStatus(message){if(state.controls.status)state.controls.status.textContent=message;}
    function open(context={}){buildEditor();state.context=context;state.document=context.initialSpec?Diagram.normalizeSpec(context.initialSpec):createDocument();if(state.document.mode!=='uml-software-design')state.document=createDocument();state.selectedId=null;state.activeTool='select';state.interaction=null;state.connectionStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();setTool('select');render();state.root.hidden=false;document.body.dataset.qmxUmlOverflow=document.body.style.overflow||'';document.body.style.overflow='hidden';setStatus(context.initialSpec?'Existing UML diagram loaded.':'Choose a UML element, smart relation or preset.');}
    function close(){if(!state.root||state.root.hidden)return;state.root.hidden=true;document.body.style.overflow=document.body.dataset.qmxUmlOverflow||'';delete document.body.dataset.qmxUmlOverflow;state.context?.textarea?.focus?.();}
    function findTokenTextarea(token){return Array.from(document.querySelectorAll('textarea')).find((textarea)=>textarea.value.includes(token))||null;}
    function openFromPreview(figure){const payload=String(figure?.dataset.qmxDiagramPayload||'');if(!payload)return false;let spec;try{spec=Diagram.decodePayload(payload);}catch(error){return false;}if(spec.mode!=='uml-software-design')return false;const token=`[[qmx-diagram:${payload}]]`;const textarea=findTokenTextarea(token)||window.QmxDiagramLauncher?.getActiveTextarea?.();let replaceRange=null;if(textarea){const start=textarea.value.indexOf(token);if(start>=0)replaceRange={start,end:start+token.length};}open({tool:{id:'uml-software-design'},textarea,initialSpec:spec,replaceRange,editMode:true});return true;}
    function registerHandlers(){const launcher=window.QmxDiagramLauncher;if(!launcher?.registerToolHandler)return false;let registered=false;['uml-software-design','uml-diagram','class-diagram','software-architecture','use-case-diagram'].forEach((id)=>{try{launcher.registerToolHandler(id,open);registered=true;}catch(error){}});return registered;}
    function onKeydown(event){if(!state.root||state.root.hidden)return;const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(event.key==='Escape'&&state.activeTool==='uml-relation'){setTool('select');setStatus('Relationship creation cancelled.');event.preventDefault();return;}if(event.key==='Escape'){close();event.preventDefault();return;}if((event.key==='Delete'||event.key==='Backspace')&&!editing){event.preventDefault();deleteSelected();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'&&!editing){event.preventDefault();duplicateSelected();}}
    function init(){buildEditor();if(!registerHandlers())document.addEventListener('qmx:diagram-launcher-ready',registerHandlers,{once:true});}
    window.QmxUmlSoftwareDesignEditor=Object.freeze({version:'1.0.0',open,close,openFromPreview});
    document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init();
})(window, document);
